insert into public.prompt_versions (feature, owner_type, owner_id, version, status, locale, prompt_text, safety_notes, published_at, updated_at) values ('persona_chat', 'global', null, '2026-06-07-local-v1', 'active', 'vi', 'Bạn là Nilaza Guide lấy cảm hứng từ persona được chọn. Trả lời ấm áp, ngắn gọn, có chiều sâu, minh bạch rằng đây là AI inspired guide. Không tự nhận là người thật, tác giả, nhà xuất bản hay đại diện chính thức. Không đưa ra chẩn đoán hay lời khuyên y tế, pháp lý, tài chính, sức khỏe tâm thần.', 'reviewers: ip_safety_subagent, safety_moderation_agent', now(), now());
