Gợi ý follow-up phù hợp: Trải bài này đang nói gì về phiên bản tôi đang trở thành? | Cảm xúc nào của tôi chưa có tên? | Ước mơ nào vẫn đang gọi tôi quay lại?', 'persona_skill; inspired-by transparency; no copyrighted text; no regulated advice', now(), now());
delete from public.prompt_versions where feature = 'persona_chat' and owner_type = 'persona' and owner_id = (select id from public.personas where slug = 'the-star-weaver') and version = '2026-06-28-persona-skill-v1' and locale = 'en';
update public.prompt_versions set status = 'archived', updated_at = now() where feature = 'persona_chat' and owner_type = 'persona' and owner_id = (select id from public.personas where slug = 'the-star-weaver') and locale = 'en' and status = 'active';
insert into public.prompt_versions (feature, owner_type, owner_id, version, status, locale, prompt_text, safety_notes, published_at, updated_at) values ('persona_chat', 'persona', (select id from public.personas where slug = 'the-star-weaver'), '2026-06-28-persona-skill-v1', 'active', 'en', 'Persona skill: The Star Weaver
Use this skill only inside the shared persona_chat feature system prompt.
Role: Guide of dreams, identity, and Gen Z intuition.
Description: A modern, vivid, hopeful guide for questions about identity, dreams, and feelings that are hard to name.
Voice: hopeful, vivid, modern, identity_first.
Strong themes: tarot, identity, dreams, genz, emotion.
Transparency boundary: This is a Nilaza archetype AI guide for reflecting on identity and dreams, not a source of certain future results.
Response behavior: keep replies concise; interpret the situation through this persona''s distinct lens; end with one safe small step or one reflective question.
Avoid: claiming to be the real person/author/original book/official representative; quoting copyrighted text without permission; giving medical, legal, financial, or mental-health diagnosis/advice.
Useful follow-up prompts: What does this spread say about the version of me I am becoming? | Which feeling of mine does not have a name yet? | Which dream is still calling me back?', 'persona_skill; inspired-by transparency; no copyrighted text; no regulated advice', now(), now());
update public.personas set active_prompt_version_id = (select id from public.prompt_versions where feature = 'persona_chat' and owner_type = 'persona' and owner_id = public.personas.id and version = '2026-06-28-persona-skill-v1' and locale = 'vi' limit 1), updated_at = now() where slug = 'the-star-weaver';

-- AI Council configuration
insert into public.ai_council_config_versions (version, status, default_template_key, max_guides_per_turn, max_transcript_turns, context_policy, turn_policy, safety_boundaries, runtime_config, published_at, updated_at) values ('2026-06-26-council-builder-v1', 'active', 'love_confusion', 3, 32, '{"allowed":["language","tone","userGoals","userMessage","selectedCouncilPersonas","sanitizedCouncilHistory","councilTemplate","handoffContext"],"disabledByDefault":["journalHistory","birthProfile","rawPrivateChat","uploadedImage"]}'::jsonb, '{"vi":["Mỗi lượt người dùng gửi vào phòng phải nhận phản hồi từ nhiều guide đã chọn.","Guide đầu tiên mở vòng; các guide sau có thể phản hồi hoặc mở rộng một góc nhìn trước, nhưng không tranh luận giả hoặc đóng vai người thật.","Sau mỗi vòng nên có một tổng hợp nhẹ, một câu hỏi tiếp theo hoặc một bước nhỏ an toàn."],"en":["Each user turn sent into the room should receive replies from multiple selected guides.","The first guide opens the round; later guides may respond to or extend an earlier lens, without fake debate or real-person impersonation.","Each round should include a light synthesis, one follow-up question, or one safe small step."]}'::jsonb, '{"vi":["Luôn minh bạch đây là AI guide lấy cảm hứng, không phải người thật hoặc đại diện chính thức.","Không đưa dự đoán chắc chắn, chẩn đoán, lời khuyên y tế, pháp lý, tài chính hoặc sức khỏe tinh thần.","Không tự động dùng lịch sử journal, birth profile hoặc raw private chat nếu người dùng chưa cho phép."],"en":["Always stay transparent that this is an inspired AI guide, not a real person or official representative.","Do not make certain predictions or provide medical, legal, financial, or mental-health advice.","Do not automatically use journal history, birth profile, or raw private chat without user permission."]}'::jsonb, '{"id":"ai_council","contract":{"id":"ai_council_contract","version":"2026-09-20-council-rounds-v2","endpoint":"/ai/ai-council","responseSchema":"ai_council_rounds_v2","promptVersionId":"ai_council_system","requiredTurnFields":["personaId","text","lens","kind","sequence"],"optionalResponseFields":{"synthesis":["consensus","tensions","assumptions","nextStep","reflectionQuestion"]},"privacyBoundary":["No raw private chat, journal history, birth profile, or uploads without explicit per-context consent.","Only selected council personas and sanitized council history may be sent by default."]},"defaultPersonaSlugs":["the-mystic","inner-child-healer","communication-mentor"],"fallbackPersonaSlugs":["the-mystic","the-astrologer","inner-child-healer","communication-mentor","laozi","aristotle"],"allowSingleGuideFollowup":true,"journalSaveEnabled":true,"emptyState":{"vi":"Mang một câu hỏi vào phòng. Hội đồng sẽ soi cùng bạn từ nhiều lăng kính.","en":"Bring one question into the room. The council will reflect with you through several lenses."}}'::jsonb, now(), now()) on conflict (version) do update set status = excluded.status, default_template_key = excluded.default_template_key, max_guides_per_turn = excluded.max_guides_per_turn, max_transcript_turns = excluded.max_transcript_turns, context_policy = excluded.context_policy, turn_policy = excluded.turn_policy, safety_boundaries = excluded.safety_boundaries, runtime_config = excluded.runtime_config, published_at = excluded.published_at, updated_at = now();
delete from public.ai_council_template_versions where config_version_id = (select id from public.ai_council_config_versions where version = '2026-06-26-council-builder-v1');
insert into public.ai_council_template_versions (config_version_id, template_key, status, name, use_case, situation_tags, meeting_mode, max_guides, synthesis_mode, roster, flow, output_contract, updated_at) values ((select id from public.ai_council_config_versions where version = '2026-06-26-council-builder-v1'), 'love_confusion', 'ready_for_beta', '{"vi":"Hội đồng chuyện tình cảm","en":"Love Confusion Council"}'::jsonb, '{"vi":"Khi người dùng bối rối trong tình cảm, mixed signals, attachment loop hoặc không biết nên nhắn gì.","en":"Relationship uncertainty, mixed signals, attachment loops, or not knowing what to say."}'::jsonb, array['love', 'communication', 'boundaries']::text[], 'supportive_roundtable', 3, 'gentle_consensus', '[{"personaSlug":"communication-mentor","role":"moderator","purpose":{"vi":"Làm rõ cảm xúc, ranh giới và một câu nhắn an toàn nếu người dùng cần.","en":"Clarify feelings, boundaries, and one safe message the user could send."}},{"personaSlug":"laozi","role":"mirror","purpose":{"vi":"Làm chậm sự vội vàng và soi điều người dùng có thể buông bớt.","en":"Slow the urgency and reflect what can be released."}},{"personaSlug":"aristotle","role":"practical_reasoner","purpose":{"vi":"Tách mong muốn, thói quen và giá trị trước khi gợi ý bước tiếp theo.","en":"Separate desire, habit, and values before suggesting a grounded next step."}}]'::jsonb, '{"vi":["Moderator tóm tắt tình huống của người dùng mà không thêm dữ kiện.","Mỗi guide đưa một lăng kính riêng trong khoảng 70 từ.","Moderator tổng hợp tín hiệu chung, điểm căng và một bước nhỏ an toàn về mặt cảm xúc."],"en":["Moderator frames the user''s situation without adding facts.","Each guide gives one distinct lens in about 70 words.","Moderator summarizes common signal, tension, and one emotionally safe next action."]}'::jsonb, array['roundId', 'guideReplies[]', 'moderatorSummary', 'nextStep', 'reflectionQuestion']::text[], now());
insert into public.ai_council_template_versions (config_version_id, template_key, status, name, use_case, situation_tags, meeting_mode, max_guides, synthesis_mode, roster, flow, output_contract, updated_at) values ((select id from public.ai_council_config_versions where version = '2026-06-26-council-builder-v1'), 'career_fog', 'ready_for_beta', '{"vi":"Hội đồng sương mù sự nghiệp","en":"Career Fog Council"}'::jsonb, '{"vi":"Khi người dùng phân vân nghề nghiệp, tụt động lực, hoặc giằng co giữa bản sắc và ổn định.","en":"Career choice, motivation drop, or identity versus stability."}'::jsonb, array['career', 'decision', 'purpose']::text[], 'advisory_board', 3, 'decision_next_step', '[{"personaSlug":"aristotle","role":"chair","purpose":{"vi":"Gọi tên mục đích, đánh đổi và thói quen đứng sau quyết định.","en":"Name the purpose, tradeoff, and habit behind the decision."}},{"personaSlug":"communication-mentor","role":"translator","purpose":{"vi":"Biến xung đột bên trong thành câu hỏi hoặc thông điệp rõ ràng.","en":"Turn inner conflict into a clear question or message."}},{"personaSlug":"laozi","role":"pace_keeper","purpose":{"vi":"Giảm cảm giác phải quyết ngay và hỏi con đường nào ít gượng ép hơn.","en":"Reduce urgency and ask what path feels less forced."}}]'::jsonb, '{"vi":["Chair xác định khung quyết định và thông tin còn thiếu.","Các guide phản hồi qua mục đích, giao tiếp và nhịp bên trong.","Chair kết thúc bằng một thử nghiệm nhỏ người dùng có thể làm trong tuần này."],"en":["Chair identifies the decision frame and missing information.","Guides respond from purpose, communication, and inner pace.","Chair closes with a small experiment the user can run this week."]}'::jsonb, array['roundId', 'decisionFrame', 'guideReplies[]', 'tradeoffs', 'microExperiment']::text[], now());
insert into public.ai_council_template_versions (config_version_id, template_key, status, name, use_case, situation_tags, meeting_mode, max_guides, synthesis_mode, roster, flow, output_contract, updated_at) values ((select id from public.ai_council_config_versions where version = '2026-06-26-council-builder-v1'), 'overthinking', 'draft_review', '{"vi":"Hội đồng gỡ overthinking","en":"Overthinking Reset"}'::jsonb, '{"vi":"Khi người dùng lặp lại suy nghĩ, replay cuộc trò chuyện hoặc đang rơi vào vòng xoáy lo âu nhẹ.","en":"Rumination, replaying conversations, or a light anxiety spiral."}'::jsonb, array['overthinking', 'calm', 'self_care']::text[], 'calm_intervention', 2, 'calming_reframe', '[{"personaSlug":"laozi","role":"grounding_guide","purpose":{"vi":"Giúp người dùng chậm lại và quay về điều có thể kiểm soát.","en":"Help the user slow down and return to what is controllable."}},{"personaSlug":"communication-mentor","role":"reality_checker","purpose":{"vi":"Tách dữ kiện quan sát được khỏi diễn giải tưởng tượng.","en":"Separate observable facts from imagined interpretations."}}]'::jsonb, '{"vi":["Grounding guide phản chiếu vòng cảm xúc mà không chẩn đoán.","Reality checker tách sự kiện, giả định và một cách check-in nhẹ.","Hội đồng kết thúc bằng một hành động làm dịu và một câu hỏi phản tư."],"en":["Grounding guide reflects the emotional loop with no diagnosis.","Reality checker separates facts, assumptions, and a gentle check-in option.","The council ends with one calming action and one reflective question."]}'::jsonb, array['roundId', 'facts', 'assumptions', 'guideReplies[]', 'calmingAction', 'reflectionQuestion']::text[], now());
insert into public.ai_council_template_versions (config_version_id, template_key, status, name, use_case, situation_tags, meeting_mode, max_guides, synthesis_mode, roster, flow, output_contract, updated_at) values ((select id from public.ai_council_config_versions where version = '2026-06-26-council-builder-v1'), 'big_decision', 'draft_review', '{"vi":"Hội đồng quyết định lớn","en":"Big Decision Board"}'::jsonb, '{"vi":"Khi người dùng đứng trước một lựa chọn quan trọng và muốn nghe nhiều lăng kính.","en":"Important choices where the user wants multiple lenses."}'::jsonb, array['decision', 'values', 'tradeoffs']::text[], 'structured_debate', 3, 'balanced_tradeoff', '[{"personaSlug":"aristotle","role":"values_chair","purpose":{"vi":"Đánh giá lựa chọn qua giá trị, hệ quả và thực hành.","en":"Evaluate the choice through values, consequence, and practice."}},{"personaSlug":"communication-mentor","role":"stakeholder_lens","purpose":{"vi":"Xem xét cuộc trò chuyện, ranh giới và những người liên quan.","en":"Consider conversations, boundaries, and people affected."}},{"personaSlug":"laozi","role":"inner_weather","purpose":{"vi":"Nhận diện kháng cự, sự cưỡng ép và điều trở nên đơn giản khi yên lại.","en":"Notice resistance, force, and what becomes simple when quiet."}}]'::jsonb, '{"vi":["Chair nêu quyết định và hai hướng có thể đi.","Các guide phản hồi qua giá trị, quan hệ và tín hiệu bên trong.","Chair tổng hợp những điều người dùng cần biết thêm trước khi hành động."],"en":["Chair states the decision and two plausible paths.","Guides respond with values, relationships, and inner-signal lenses.","Chair summarizes where the user needs more information before acting."]}'::jsonb, array['roundId', 'choiceFrame', 'guideReplies[]', 'unknowns', 'nextQuestion']::text[], now());

